CREATE TABLE dbo.Rooms (
  RoomId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Rooms_Id DEFAULT NEWSEQUENTIALID(),
  BranchId UNIQUEIDENTIFIER NOT NULL, Code VARCHAR(30) NOT NULL, Name NVARCHAR(150) NOT NULL,
  RoomType VARCHAR(30) NOT NULL CONSTRAINT DF_Rooms_Type DEFAULT 'CHAIR', IsActive BIT NOT NULL CONSTRAINT DF_Rooms_Active DEFAULT 1,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Rooms_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Rooms PRIMARY KEY(RoomId), CONSTRAINT FK_Rooms_Branches FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId),
  CONSTRAINT UQ_Rooms_Branch_Code UNIQUE(BranchId, Code), CONSTRAINT CK_Rooms_Type CHECK(RoomType IN ('ROOM','CHAIR','LAB','STERILIZATION'))
);
CREATE TABLE dbo.Services (
  ServiceId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Services_Id DEFAULT NEWSEQUENTIALID(), Code VARCHAR(30) NOT NULL,
  Name NVARCHAR(200) NOT NULL, RequiresConsent BIT NOT NULL CONSTRAINT DF_Services_Consent DEFAULT 0,
  RequiresSterilePack BIT NOT NULL CONSTRAINT DF_Services_Pack DEFAULT 0, IsActive BIT NOT NULL CONSTRAINT DF_Services_Active DEFAULT 1,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Services_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Services PRIMARY KEY(ServiceId), CONSTRAINT UQ_Services_Code UNIQUE(Code)
);
CREATE TABLE dbo.ServicePriceVersions (
  PriceVersionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_PriceVersions_Id DEFAULT NEWSEQUENTIALID(), ServiceId UNIQUEIDENTIFIER NOT NULL,
  BranchId UNIQUEIDENTIFIER NULL, VersionNo INT NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL, EffectiveFrom DATETIME2 NOT NULL,
  EffectiveTo DATETIME2 NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_PriceVersions_Status DEFAULT 'DRAFT',
  ApprovedBy UNIQUEIDENTIFIER NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_PriceVersions_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_ServicePriceVersions PRIMARY KEY(PriceVersionId), CONSTRAINT FK_PriceVersions_Service FOREIGN KEY(ServiceId) REFERENCES dbo.Services(ServiceId),
  CONSTRAINT FK_PriceVersions_Branch FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId), CONSTRAINT FK_PriceVersions_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT UQ_PriceVersions_Service_Branch_Version UNIQUE(ServiceId, BranchId, VersionNo),
  CONSTRAINT CK_PriceVersions_Amount CHECK(UnitPrice >= 0), CONSTRAINT CK_PriceVersions_Period CHECK(EffectiveTo IS NULL OR EffectiveTo > EffectiveFrom),
  CONSTRAINT CK_PriceVersions_Status CHECK(Status IN ('DRAFT','APPROVED','RETIRED'))
);
CREATE TABLE dbo.TaxRateVersions (
  TaxRateVersionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TaxRates_Id DEFAULT NEWSEQUENTIALID(), ScopeCode VARCHAR(80) NOT NULL,
  VersionNo INT NOT NULL, RatePercent DECIMAL(7,4) NOT NULL, EffectiveFrom DATETIME2 NOT NULL, EffectiveTo DATETIME2 NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_TaxRates_Status DEFAULT 'DRAFT', ApprovedBy UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_TaxRates_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_TaxRateVersions PRIMARY KEY(TaxRateVersionId), CONSTRAINT FK_TaxRates_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT UQ_TaxRates_Scope_Version UNIQUE(ScopeCode, VersionNo), CONSTRAINT CK_TaxRates_Rate CHECK(RatePercent BETWEEN 0 AND 100),
  CONSTRAINT CK_TaxRates_Period CHECK(EffectiveTo IS NULL OR EffectiveTo > EffectiveFrom), CONSTRAINT CK_TaxRates_Status CHECK(Status IN ('DRAFT','APPROVED','RETIRED'))
);
CREATE TABLE dbo.DiscountPolicies (
  DiscountPolicyId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_DiscountPolicies_Id DEFAULT NEWSEQUENTIALID(), Code VARCHAR(50) NOT NULL,
  Name NVARCHAR(200) NOT NULL, MaxPercent DECIMAL(7,4) NOT NULL, ApprovalThreshold DECIMAL(18,2) NOT NULL,
  EffectiveFrom DATETIME2 NOT NULL, EffectiveTo DATETIME2 NULL, ApprovedBy UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_DiscountPolicies_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_DiscountPolicies PRIMARY KEY(DiscountPolicyId), CONSTRAINT UQ_DiscountPolicies_Code UNIQUE(Code),
  CONSTRAINT FK_DiscountPolicies_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT CK_DiscountPolicies_Percent CHECK(MaxPercent BETWEEN 0 AND 100), CONSTRAINT CK_DiscountPolicies_Threshold CHECK(ApprovalThreshold >= 0),
  CONSTRAINT CK_DiscountPolicies_Period CHECK(EffectiveTo IS NULL OR EffectiveTo > EffectiveFrom)
);
CREATE TABLE dbo.AccountingRuleVersions (
  AccountingRuleVersionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_AccountingRules_Id DEFAULT NEWSEQUENTIALID(), EventType VARCHAR(80) NOT NULL,
  VersionNo INT NOT NULL, RuleJson NVARCHAR(MAX) NOT NULL, EffectiveFrom DATETIME2 NOT NULL, EffectiveTo DATETIME2 NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_AccountingRules_Status DEFAULT 'DRAFT', ApprovedBy UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_AccountingRules_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_AccountingRuleVersions PRIMARY KEY(AccountingRuleVersionId), CONSTRAINT UQ_AccountingRules_Event_Version UNIQUE(EventType, VersionNo),
  CONSTRAINT FK_AccountingRules_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_AccountingRules_Json CHECK(ISJSON(RuleJson)=1),
  CONSTRAINT CK_AccountingRules_Period CHECK(EffectiveTo IS NULL OR EffectiveTo > EffectiveFrom), CONSTRAINT CK_AccountingRules_Status CHECK(Status IN ('DRAFT','APPROVED','RETIRED'))
);
CREATE TABLE dbo.Suppliers (
  SupplierId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Suppliers_Id DEFAULT NEWSEQUENTIALID(), Code VARCHAR(30) NOT NULL, Name NVARCHAR(200) NOT NULL,
  Phone VARCHAR(30) NULL, TaxCode VARCHAR(30) NULL, IsActive BIT NOT NULL CONSTRAINT DF_Suppliers_Active DEFAULT 1,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Suppliers_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Suppliers PRIMARY KEY(SupplierId), CONSTRAINT UQ_Suppliers_Code UNIQUE(Code)
);
CREATE TABLE dbo.SystemConfigVersions (
  ConfigVersionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ConfigVersions_Id DEFAULT NEWSEQUENTIALID(), ConfigKey VARCHAR(100) NOT NULL,
  ScopeCode VARCHAR(100) NOT NULL CONSTRAINT DF_ConfigVersions_Scope DEFAULT 'GLOBAL', VersionNo INT NOT NULL, ValueJson NVARCHAR(MAX) NOT NULL,
  EffectiveFrom DATETIME2 NOT NULL, EffectiveTo DATETIME2 NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_ConfigVersions_Status DEFAULT 'DRAFT',
  ApprovedBy UNIQUEIDENTIFIER NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ConfigVersions_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_SystemConfigVersions PRIMARY KEY(ConfigVersionId), CONSTRAINT UQ_ConfigVersions_Key_Scope_Version UNIQUE(ConfigKey, ScopeCode, VersionNo),
  CONSTRAINT FK_ConfigVersions_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_ConfigVersions_Json CHECK(ISJSON(ValueJson)=1),
  CONSTRAINT CK_ConfigVersions_Period CHECK(EffectiveTo IS NULL OR EffectiveTo > EffectiveFrom), CONSTRAINT CK_ConfigVersions_Status CHECK(Status IN ('DRAFT','APPROVED','RETIRED'))
);
CREATE TABLE dbo.ConsentTemplates (
  ConsentTemplateId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ConsentTemplates_Id DEFAULT NEWSEQUENTIALID(), ServiceId UNIQUEIDENTIFIER NULL,
  Code VARCHAR(50) NOT NULL, VersionNo INT NOT NULL, Title NVARCHAR(200) NOT NULL, Content NVARCHAR(MAX) NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_ConsentTemplates_Status DEFAULT 'DRAFT', EffectiveFrom DATETIME2 NOT NULL, EffectiveTo DATETIME2 NULL,
  ApprovedBy UNIQUEIDENTIFIER NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ConsentTemplates_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_ConsentTemplates PRIMARY KEY(ConsentTemplateId), CONSTRAINT FK_ConsentTemplates_Service FOREIGN KEY(ServiceId) REFERENCES dbo.Services(ServiceId),
  CONSTRAINT FK_ConsentTemplates_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId), CONSTRAINT UQ_ConsentTemplates_Code_Version UNIQUE(Code, VersionNo),
  CONSTRAINT CK_ConsentTemplates_Period CHECK(EffectiveTo IS NULL OR EffectiveTo > EffectiveFrom), CONSTRAINT CK_ConsentTemplates_Status CHECK(Status IN ('DRAFT','APPROVED','RETIRED'))
);
